var ganttZoom = 48;
var ganttScrub = 0;
var wrap = byIdEl("diagWrap");
var tipEl = byIdEl("tip");

function formatGanttBarLabel(ev, zoom) {
  var pct = (ev.durH / zoom) * 100;
  if (pct < 7.5) {
    return esc(ev.id);
  }
  if (pct < 15) {
    if (ev.type === "transit") return esc(ev.id + " · " + hhmm(NOW + ev.durH * 3600000));
    return esc(ev.id + " · " + ev.bed);
  }
  return esc(ev.id + " · " + ev.title);
}

function renderGanttGrid() {
  var ticks = [];
  var step = ganttZoom / 8;
  for (var i = 0; i < 8; i++) {
    var h = i * step;
    var t = NOW + h * 3600000;
    var isNow = i === 0;
    ticks.push(
      '<div class="ganttTick' + (isNow ? ' nowTick' : '') + '">' +
      (isNow ? 'NOW (' + hhmm(t) + ')' : '+' + Math.round(h) + 'h (' + hhmm(t) + ')') +
      '</div>'
    );
  }

  var cursorPct = (ganttScrub / ganttZoom) * 100;
  var h = [];
  h.push('<div class="ganttGridTable">');

  h.push(
    '<div class="ganttCursor" id="ganttCursor" style="left: calc(175px + ' + cursorPct + '% * 0.81);">' +
    '<div class="ganttCursorPin" id="ganttCursorPin">' + (ganttScrub === 0 ? 'NOW ' + hhmm(NOW) : '+' + ganttScrub + 'h') + '</div>' +
    '</div>'
  );

  h.push(
    '<div class="ganttHeaderRow">' +
    '<div class="ganttColWard">Ward / Receiving Unit</div>' +
    '<div class="ganttColTicks">' + ticks.join('') + '</div>' +
    '</div>'
  );

  GANTT_LANES.forEach(function (lane) {
    h.push('<div class="ganttLaneRow">');
    h.push(
      '<div class="ganttLaneLabel" title="' + esc(lane.name) + '">' +
      '<span>' + esc(lane.name) + '</span>' +
      '<span class="ganttSvcTag">' + esc(lane.service) + '</span>' +
      '</div>'
    );
    h.push('<div class="ganttLaneTrack">');

    for (var c = 0; c < 8; c++) {
      h.push('<div class="ganttLaneCol"></div>');
    }

    lane.events.forEach(function (ev) {
      if (ev.startH < ganttZoom) {
        var leftPct = (ev.startH / ganttZoom) * 100;
        var widthPct = Math.max((ev.durH / ganttZoom) * 100, 3.2);
        var maxW = 100 - leftPct;
        var actualW = Math.min(widthPct, maxW);
        var barText = formatGanttBarLabel(ev, ganttZoom);

        h.push(
          '<div class="ganttBarItem ' + ev.type + (state.movementId === ev.id ? ' activeSelect' : '') + '" ' +
          'style="left:' + leftPct.toFixed(2) + '%; width:' + actualW.toFixed(2) + '%;" ' +
          'data-mid="' + esc(ev.id) + '" ' +
          'data-head="' + esc(ev.id + " · " + ev.title) + '" ' +
          'data-words="' + esc(ev.origin + " ➔ " + ev.dest + " · " + ev.carrier + " · " + ev.bed) + '" ' +
          'tabindex="0" role="button" aria-label="' + esc(ev.id + " " + ev.title) + '">' +
          barText +
          '</div>'
        );
      }
    });

    h.push('</div></div>');
  });

  h.push('</div>');
  return h.join('');
}

function updateGantt() {
  if (!wrap) return;
  wrap.innerHTML = renderGanttGrid() + '<div class="tip" id="tip" aria-hidden="true"></div>';
  tipEl = byIdEl("tip");
}

updateGantt();

byIdEl("diagNote").textContent = "48-hour bed horizon: tracking 24 active transfers, 11 Form 5A trial leaves, and 19 planned discharges across Western Australia.";
byIdEl("diagFootText").innerHTML = "<span>" + esc(diagramFootText()) + "</span>";

// Wire Scrubber
var scrubberEl = byIdEl("ganttScrubber");
if (scrubberEl) {
  scrubberEl.addEventListener("input", function () {
    ganttScrub = parseInt(this.value, 10);
    byIdEl("ganttScrubText").textContent = ganttScrub === 0 ? "NOW (+0h)" : "+" + ganttScrub + "h (" + hhmm(NOW + ganttScrub * 3600000) + ")";
    var cursor = byIdEl("ganttCursor");
    var pin = byIdEl("ganttCursorPin");
    if (cursor) {
      var cursorPct = (ganttScrub / ganttZoom) * 100;
      cursor.style.left = "calc(175px + " + cursorPct + "% * 0.81)";
    }
    if (pin) {
      pin.textContent = ganttScrub === 0 ? "NOW " + hhmm(NOW) : "+" + ganttScrub + "h";
    }
  });
}

var resetBtn = byIdEl("ganttResetBtn");
if (resetBtn) {
  resetBtn.addEventListener("click", function () {
    if (scrubberEl) {
      scrubberEl.value = 0;
      scrubberEl.dispatchEvent(new Event("input"));
    }
  });
}

// Wire Zoom buttons
document.querySelectorAll(".zmBtn").forEach(function (btn) {
  btn.addEventListener("click", function () {
    document.querySelectorAll(".zmBtn").forEach(function (b) { b.classList.remove("active"); b.setAttribute("aria-pressed", "false"); });
    btn.classList.add("active");
    btn.setAttribute("aria-pressed", "true");
    ganttZoom = parseInt(btn.getAttribute("data-zoom"), 10);
    updateGantt();
  });
});

// Wire Enlarge button
var enlargeBtn = byIdEl("enlargeGantt");
if (enlargeBtn) {
  enlargeBtn.addEventListener("click", function () {
    var split = byIdEl("diagSplit");
    if (!split) return;
    var isEnlarged = split.classList.toggle("enlarged");
    enlargeBtn.setAttribute("aria-pressed", isEnlarged ? "true" : "false");
    enlargeBtn.textContent = isEnlarged ? "Normal view" : "Enlarge";
    announce(isEnlarged ? "Movement horizon enlarged to full width" : "Movement horizon restored to split view");
  });
}

// Hover tooltip for Gantt bars
wrap.addEventListener("mousemove", function (ev) {
  var t = ev.target.closest ? ev.target.closest(".ganttBarItem") : null;
  if (!t) {
    if (tipEl) tipEl.classList.remove("on");
    return;
  }
  tipEl.innerHTML =
    "<b>" + esc(t.getAttribute("data-head")) + "</b><em>" + esc(t.getAttribute("data-words")) + "</em>";
  var r = wrap.getBoundingClientRect();
  tipEl.style.left = Math.max(6, Math.min(ev.clientX - r.left + 14, wrap.clientWidth - 280)) + "px";
  tipEl.style.top = ev.clientY - r.top + 16 + "px";
  tipEl.classList.add("on");
});

wrap.addEventListener("mouseleave", function () {
  if (tipEl) tipEl.classList.remove("on");
});

// Click on Gantt bar selects movement in worklist and opens detail drawer
wrap.addEventListener("click", function (ev) {
  var t = ev.target.closest ? ev.target.closest(".ganttBarItem") : null;
  if (!t) return;
  var mid = t.getAttribute("data-mid");
  selectMovement(mid);
  announce("Selected movement " + mid + " from timeline.");
});

