   off the real widths, on load and on every resize, and the note appears only
   when it is true. */
function updateDiagramAffordance() {
  if (!wrap) return;
  var over = wrap.scrollWidth > wrap.clientWidth + 1;
  wrap.setAttribute("data-overflowing", over ? "true" : "false");
  var note = byIdEl("diagScrollNote");
  if (note) note.hidden = !over;
}
(function () {
  var raf = null;
  window.addEventListener("resize", function () {
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(updateDiagramAffordance);
  });
})();

/* The transparent hit path sits above the corridor it belongs to, so a CSS hover
   on the corridor can never fire. The highlight is applied by hand, to the line
   and to its label, from whichever hit path the pointer or the focus ring is on. */
function setHover(cid) {
  document.querySelectorAll(".corridor, .cLabel").forEach(function (el) {
    el.classList.toggle("hov", !!cid && el.getAttribute("data-cid") === cid);
