    tipEl.classList.remove("on");
    setHover(null);
    return;
  }
  setHover(t.getAttribute("data-cid"));
  tipEl.innerHTML =
    "<b>" + esc(t.getAttribute("data-head")) + "</b><em>" + esc(t.getAttribute("data-words")) + "</em>";
  var r = wrap.getBoundingClientRect();
  tipEl.style.left = Math.max(6, Math.min(ev.clientX - r.left + 14, wrap.clientWidth - 280)) + "px";
  tipEl.style.top = ev.clientY - r.top + 16 + "px";
  tipEl.classList.add("on");
});
wrap.addEventListener("mouseleave", function () {
  tipEl.classList.remove("on");
  setHover(null);
});
wrap.addEventListener("focusin", function (ev) {
  var t = ev.target.closest ? ev.target.closest(".hit") : null;
  setHover(t ? t.getAttribute("data-cid") : null);
});
wrap.addEventListener("focusout", function () {
  setHover(null);
});
wrap.addEventListener("click", function (ev) {
  var t = ev.target.closest ? ev.target.closest(".hit") : null;
  if (!t) return;
  var cid = t.getAttribute("data-cid");
  if (state.filter && state.filter.cid === cid) {
    setFilter(null);
    announce("Corridor filter cleared. All " + open.length + " open movements shown.");
    return;

