// Click on Gantt bar selects movement in worklist and opens detail drawer
wrap.addEventListener("click", function (ev) {
  var t = ev.target.closest ? ev.target.closest(".ganttBarItem") : null;
  if (!t) return;
  var mid = t.getAttribute("data-mid");
  selectMovement(mid);
  requestAnimationFrame(function () {
    var d = byIdEl("mvDetail");
    if (d && state.movementId === mid) d.open = true;
  });
  announce("Selected movement " + mid + " from timeline.");
});

