/* 6. where thickness alone cannot carry the range, the foot notes it */
if (!thicknessAlone) {
  if (byIdEl("diagFootText") && byIdEl("diagFootText").textContent.indexOf("too flat") === -1)
    problems.push("the diagram foot does not say the thickness range is too flat to read on its own");
}

/* 7. no gantt event bar in a lane overlaps another */
(function () {
  GANTT_LANES.forEach(function (lane) {
    var evs = lane.events || [];
    for (var i = 0; i < evs.length; i++) {
      for (var j = i + 1; j < evs.length; j++) {
        var a = evs[i], b = evs[j];
        var aEnd = a.startH + a.durH;
        var bEnd = b.startH + b.durH;
        if (a.startH < bEnd && b.startH < aEnd) {
          problems.push("lane " + lane.name + " events " + a.id + " and " + b.id + " overlap in time");
        }
      }
    }
  });
})();

