/* 6. where thickness alone cannot carry the range, every carried line writes
      its own number, and the foot says so rather than leaving the eye to guess */
if (!thicknessAlone) {
  CORRIDORS.filter(function (c) {
    return c.kind === "carried";
  }).forEach(function (c) {
    if (!document.querySelector('.cLabel[data-cid="' + c.id + '"][data-kind="carried"]'))
      problems.push(
        "the carried range is " +
          minJourneys +
          " to " +
          maxJourneys +
          ", too flat for thickness alone, and " +
          c.id +
          " writes no number",
      );
  });
  if (byIdEl("diagFootText").textContent.indexOf("too flat") === -1)
    problems.push("the diagram foot does not say the thickness range is too flat to read on its own");
}

/* 7. no label is hidden underneath another */
(function () {
  var boxes = [];
  document.querySelectorAll(".cLabel rect").forEach(function (r) {
    boxes.push({
      cid: r.parentNode.getAttribute("data-cid"),
      x: parseFloat(r.getAttribute("x")),
      w: parseFloat(r.getAttribute("width")),
      y: parseFloat(r.getAttribute("y")),
      h: parseFloat(r.getAttribute("height")),
    });
  });
  boxes.forEach(function (a, i) {
    boxes.slice(i + 1).forEach(function (b) {
      if (a.y < b.y + b.h && b.y < a.y + a.h && a.x < b.x + b.w && b.x < a.x + a.w)
        problems.push("corridor labels " + a.cid + " and " + b.cid + " overlap, so one is unreadable");
    });
  });
  if (
    boxes.some(function (b) {
      return b.x < HUB_R;
    })
  )
    problems.push("a corridor label runs back into the coordination block");
})();

