       listed a corridor the picture does not draw, or dropped one it does, it would
       be a second source of truth rather than a second face on the same one. */
CORRIDOR_KINDS.forEach(function (k) {
  var listed = corridorsOfKind(k.key);
  var drawn = CORRIDORS.filter(function (c) {
    return c.kind === k.key;
  });
  if (listed.length !== drawn.length)
    problems.push(
      "the strip lists " + listed.length + " " + k.key + " corridors but the picture draws " + drawn.length,
    );
  listed.forEach(function (c) {
    if (!document.querySelector('.corridor[data-cid="' + c.id + '"]'))
      problems.push("the strip lists " + c.id + ", which the picture does not draw");
  });
});
(function () {
  var shown = document.querySelectorAll("#corridorList .stripRow").length;
  var expect = corridorsOfKind(state.corridorKind).length;
  if (shown !== expect) problems.push("the strip renders " + shown + " rows for " + expect + " corridors");
})();

