246: function offsetsByPair(corridors: CorridorCount[]): number[] {
247:   const groups = new Map<string, number[]>();
248:   corridors.forEach((corridor, index) => {
249:     const key = pairKey(corridor.originEdId, corridor.acceptedUnitId);
250:     groups.set(key, [...(groups.get(key) ?? []), index]);
251:   });
252:   const offsets = Array.from({ length: corridors.length }, () => 0);
253:   for (const indexes of groups.values()) {
254:     indexes.forEach((corridorIndex, pairIndex) => {
255:       offsets[corridorIndex] = (pairIndex - (indexes.length - 1) / 2) * 6;
256:     });
257:   }
258:   return offsets;
259: }
