261: function laneFor(index: number, total: number): number {
262:   if (total <= 1) return (LEFT_EDGE + RIGHT_EDGE) / 2;
263:   return LEFT_EDGE + 76 + (index / (total - 1)) * (RIGHT_EDGE - LEFT_EDGE - 152);
264: }
