266: function orthogonalRoute(y1: number, y2: number, laneX: number): string {
267:   const direction = y2 >= y1 ? 1 : -1;
268:   const radius = Math.min(10, Math.abs(y2 - y1) / 2);
269:   if (radius === 0) return `M ${LEFT_EDGE} ${y1} H ${RIGHT_EDGE}`;
270:   return `M ${LEFT_EDGE} ${y1} H ${laneX - radius} Q ${laneX} ${y1} ${laneX} ${y1 + direction * radius} V ${y2 - direction * radius} Q ${laneX} ${y2} ${laneX + radius} ${y2} H ${RIGHT_EDGE}`;
271: }
