 * 48-HOUR BED MOVEMENT HORIZON DERIVATIONS
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Operational mental model for the statewide bed flow coordinator. Maps open
 * movements, transport legs, planned admissions, trial leaves (Form 5A), and
 * projected discharges across WA health services over 12h, 24h, and 48h windows.
 */

export type MovementHorizonEventType = "admit" | "transit" | "leave" | "disch" | "pred" | "delay";

export type MovementHorizonEvent = {
  id: MovementId;
  type: MovementHorizonEventType;
  startH: number;
  durH: number;
  origin: string;
  dest: string;
  carrier: string;
  bed: string;
  title: string;
};

export type MovementHorizonLane = {
  id: string;
  name: string;
  service: "SMHS" | "EMHS" | "NMHS" | "WACHS";
  events: MovementHorizonEvent[];
};

export function deriveMovementHorizonLanes(
