/* src/components/ward-management/movements/movement-horizon.module.css
 * 48-Hour Bed Movement Horizon Stylesheet
 * Strict adherence to Ward Flow third-edition tokens and WCAG 2.1 AA contrast.
 */

.horizonContainer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  width: 100%;
  background: var(--surface);
}

.panelSubHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex-wrap: wrap;
}

.horizonNote {
  margin: 0;
  font-size: var(--t-0);
  color: var(--muted);
  flex: 1;
  min-width: 260px;
}

.phControls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.zoomGroup {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: var(--r2);
  background: var(--surface-2);
  padding: 2px;
  gap: 2px;
}

.zmBtn {
  background: transparent;
  border: none;
  font-family: var(--mono);
  font-size: var(--t-0);
  padding: 2px 8px;
  height: 24px;
  color: var(--muted);
  cursor: pointer;
  border-radius: var(--r1);
  transition: all 0.12s ease;
}

.zmBtn:hover {
  color: var(--ink);
}

.zmBtn[aria-pressed="true"] {
  background: var(--surface);
  color: var(--ink);
  font-weight: 700;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

.phBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 28px;
  padding: 0 10px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r2);
  font-family: var(--body);
  font-size: var(--t-0);
  font-weight: 600;
  color: var(--ink-soft);
  cursor: pointer;
  transition: all 0.12s ease;
}

.phBtn:hover {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--line-strong);
}

.phBtn[aria-pressed="true"] {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Controls Bar (Scrubber & Legend) */
.ganttControlsBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  flex-wrap: wrap;
}

.ganttScrubberWrap {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 280px;
  max-width: 460px;
}

.ganttScrubLabel {
  font-family: var(--mono);
  font-size: var(--t-0);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}

.ganttSlider {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: var(--sunk);
  border: 1px solid var(--line);
  outline: none;
  cursor: pointer;
}

.ganttSlider:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.ganttSlider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  cursor: pointer;
}

.ganttSlider::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  cursor: pointer;
}

.ganttScrubBadge {
  font-family: var(--mono);
  font-size: var(--t-1);
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent-soft);
  padding: 2px 8px;
  border-radius: var(--r1);
  border: 1px solid var(--line);
  min-width: 90px;
  text-align: center;
  white-space: nowrap;
}

.ganttResetBtn {
  height: 24px;
  padding: 0 8px;
  font-family: var(--mono);
  font-size: 11px;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: var(--r1);
  color: var(--muted);
  cursor: pointer;
}

.ganttResetBtn:hover {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--line-strong);
}

.ganttLegend {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: var(--t-0);
  color: var(--ink-soft);
}

.ganttLegendItem {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ganttSwatch {
  width: 10px;
  height: 8px;
  border-radius: 2px;
  display: inline-block;
}

.swatchAdmit {
  background: var(--accent);
}

.swatchTransit {
  background: var(--svc-north);
}

.swatchLeave {
  background: var(--gilt-soft);
  background-image: repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(0, 0, 0, 0.15) 2px, rgba(0, 0, 0, 0.15) 4px);
  border: 1px dashed #d4a34b;
}

.swatchDisch {
  background: var(--good);
}

.swatchPred {
  background: var(--warn-soft);
  border: 1px solid var(--warn);
}

.swatchDelay {
  background: var(--danger);
}

/* Split Area */
.diagSplit {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem);
  align-items: stretch;
  position: relative;
}

.diagSplit.enlarged {
  grid-template-columns: 1fr;
}

.diagMain {
  display: flex;
  flex-direction: column;
  min-width: 0;
  position: relative;
}

.diagWrap {
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  background: var(--surface);
  position: relative;
  scrollbar-gutter: stable;
}

.diagWrap:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Gantt Table */
.ganttGridTable {
  width: 100%;
  min-width: 760px;
  display: flex;
  flex-direction: column;
  position: relative;
  user-select: none;
}

.ganttHeaderRow {
  display: flex;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  position: sticky;
  top: 0;
  z-index: 10;
}

.ganttColWard {
  width: 175px;
  min-width: 175px;
  padding: 7px 12px;
  font-family: var(--mono);
  font-size: var(--t-0);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 600;
  border-right: 1px solid var(--line);
  background: var(--surface-2);
  display: flex;
  align-items: center;
}

.ganttColTicks {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
}

.ganttTick {
  padding: 7px 4px;
  text-align: center;
  font-family: var(--mono);
  font-size: var(--t-0);
  color: var(--ink-soft);
  border-right: 1px solid var(--line);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ganttTick.nowTick {
  font-weight: 700;
  color: var(--accent-ink);
  background: var(--accent-soft);
}

/* Scrubber Cursor */
.ganttCursor {
  position: absolute;
  top: 28px;
  bottom: 0;
  width: 2px;
  background: var(--accent);
  z-index: 20;
  pointer-events: none;
  box-shadow: 0 0 6px rgba(47, 76, 102, 0.4);
  transition: left 0.08s ease-out;
}

.ganttCursorPin {
  position: absolute;
  top: -24px;
  left: -28px;
  background: var(--accent);
  color: var(--on-accent);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--r1);
  white-space: nowrap;
}

.ganttCursorPin::after {
  content: "";
  position: absolute;
  bottom: -3px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 3px 3px 0;
  border-style: solid;
  border-color: var(--accent) transparent transparent;
}

/* Lane Row */
.ganttLaneRow {
  display: flex;
  border-bottom: 1px solid var(--line);
  height: 34px;
  min-height: 34px;
  align-items: center;
  transition: background 0.1s ease;
}

.ganttLaneRow:hover {
  background: var(--surface-2);
}

.ganttLaneLabel {
  width: 175px;
  min-width: 175px;
  height: 100%;
  padding: 0 12px;
  border-right: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-size: var(--t-1);
  font-weight: 600;
  background: var(--surface);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ganttSvcTag {
  font-family: var(--mono);
  font-size: 9.5px;
  padding: 1px 4px;
  border-radius: var(--r1);
  background: var(--sunk);
  border: 1px solid var(--line);
  color: var(--muted);
  font-weight: 600;
  flex-shrink: 0;
}

.ganttLaneTrack {
  flex: 1;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  position: relative;
}

.ganttLaneCol {
  border-right: 1px solid var(--line-strong);
  opacity: 0.25;
  height: 100%;
}

.ganttLaneCol:nth-child(even) {
  background: rgba(125, 140, 160, 0.03);
}

/* Event Bar */
.ganttBarItem {
  position: absolute;
  top: 6px;
  height: 20px;
  min-width: 52px;
  border-radius: var(--r1);
  font-size: 10.5px;
  font-family: var(--mono);
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 0 5px;
  gap: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  z-index: 5;
  border: 1px solid transparent;
}

.ganttBarItem:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.22);
  z-index: 15;
}

.ganttBarItem:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 1px;
  z-index: 25;
}

/* High Contrast Event Bar Swatches */
.barAdmit {
  background: var(--accent);
  color: #08131a;
  border-color: rgba(255, 255, 255, 0.2);
}

.barTransit {
  background: var(--svc-north);
  color: #120d1e;
  border-color: rgba(255, 255, 255, 0.25);
}

.barLeave {
  background: var(--gilt-soft);
  background-image: repeating-linear-gradient(45deg, transparent, transparent 4px, rgba(255, 216, 133, 0.08) 4px, rgba(255, 216, 133, 0.08) 8px);
  color: #ffd885;
  border: 1px dashed #d4a34b;
}

.barDisch {
  background: var(--good);
  color: #0b1510;
  border-color: rgba(255, 255, 255, 0.2);
}

.barPred {
  background: var(--warn-soft);
  border: 1px solid var(--warn);
  color: #fedb88;
}

.barDelay {
  background: var(--danger);
  color: #1a0805;
  border-color: rgba(255, 255, 255, 0.2);
}

.activeSelect {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
  z-index: 18;
}

/* Diagram Footer */
.diagFoot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-top: 1px solid var(--line);
  background: var(--surface-2);
  font-size: var(--t-0);
  color: var(--muted);
  flex-wrap: wrap;
}

.diagScope {
  font-family: var(--mono);
  font-weight: 500;
}

.schematic {
  font-style: italic;
}

/* Tooltip */
.tooltip {
  position: absolute;
  z-index: 50;
  pointer-events: none;
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--r2);
  padding: 8px 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
  font-size: var(--t-0);
  line-height: 1.4;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 280px;
}

.tooltipTitle {
  font-weight: 700;
  color: var(--ink);
  font-family: var(--mono);
}

.tooltipDetails {
  color: var(--muted);
  font-size: 11px;
}

/* Side Corridor Rail */
.corridorRail {
  min-width: 0;
  border-left: 1px solid var(--line);
  background: var(--surface);
}

.corridorRailHeader {
  display: grid;
  gap: 0.6rem;
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid var(--line);
}

.corridorRailHeader h3 {
  margin: 0;
  color: var(--accent-ink);
  font-family: var(--display);
  font-size: var(--t-3);
  font-weight: 600;
}

.corridorTabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.corridorTabs button {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  padding: 0.4rem 0.55rem;
  border: 1px solid var(--line);
  border-radius: var(--r1);
  color: var(--muted);
  background: var(--surface);
  font: inherit;
  font-size: var(--t-0);
  cursor: pointer;
  transition: all 0.12s ease;
}

.corridorTabs button:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.corridorTabs button[aria-pressed="true"] {
  border-color: var(--accent);
  color: var(--accent-ink);
  background: var(--accent-soft);
  font-weight: 600;
}

.corridorTabs span {
  font-family: var(--mono);
  font-weight: 700;
}

.corridorRanks {
  max-height: 27rem;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  list-style: none;
}

.corridorRanks li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.75rem;
  padding: 0.65rem 0.875rem;
  border-bottom: 1px solid var(--line);
}

.corridorRanks li:hover {
  background: var(--surface-2);
}

.corridorRanks li > span {
  display: grid;
  gap: 0.2rem;
  font-size: var(--t-1);
}

.corridorRanks li > span small {
  color: var(--muted);
  font-size: var(--t-0);
}

.corridorRanks li > strong {
  align-self: center;
  font-family: var(--mono);
  font-size: var(--t-1);
}

.railEmpty {
  padding: 1.25rem 0.875rem;
  margin: 0;
  color: var(--muted);
  font-size: var(--t-0);
}

/* src/components/ward-management/movements/movement-horizon.module.css
 * 48-Hour Bed Movement Horizon Stylesheet
 * Strict adherence to Ward Flow third-edition tokens and WCAG 2.1 AA contrast.
 */

.horizonContainer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  width: 100%;
  background: var(--surface);
}

.panelSubHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex-wrap: wrap;
}

.horizonNote {
  margin: 0;
  font-size: var(--t-0);
  color: var(--muted);
  flex: 1;
  min-width: 260px;
}

.phControls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.zoomGroup {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: var(--r2);
  background: var(--surface-2);
  padding: 2px;
  gap: 2px;
}

.zmBtn {
  background: transparent;
  border: none;
  font-family: var(--mono);
  font-size: var(--t-0);
  padding: 2px 8px;
  height: 24px;
  color: var(--muted);
  cursor: pointer;
  border-radius: var(--r1);
  transition: all 0.12s ease;
}

.zmBtn:hover {
  color: var(--ink);
}

.zmBtn[aria-pressed="true"] {
  background: var(--surface);
  color: var(--ink);
  font-weight: 700;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

.phBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 28px;
  padding: 0 10px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r2);
  font-family: var(--body);
  font-size: var(--t-0);
  font-weight: 600;
  color: var(--ink-soft);
  cursor: pointer;
  transition: all 0.12s ease;
}

.phBtn:hover {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--line-strong);
}

.phBtn[aria-pressed="true"] {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Controls Bar (Scrubber & Legend) */
.ganttControlsBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  flex-wrap: wrap;
}

.ganttScrubberWrap {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 280px;
  max-width: 460px;
}

.ganttScrubLabel {
  font-family: var(--mono);
  font-size: var(--t-0);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}

.ganttSlider {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: var(--sunk);
  border: 1px solid var(--line);
  outline: none;
  cursor: pointer;
}

.ganttSlider:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.ganttSlider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  cursor: pointer;
}

.ganttSlider::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  cursor: pointer;
}

.ganttScrubBadge {
  font-family: var(--mono);
  font-size: var(--t-1);
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent-soft);
  padding: 2px 8px;
  border-radius: var(--r1);
  border: 1px solid var(--line);
  min-width: 90px;
  text-align: center;
  white-space: nowrap;
}

.ganttResetBtn {
  height: 24px;
  padding: 0 8px;
  font-family: var(--mono);
  font-size: 11px;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: var(--r1);
  color: var(--muted);
  cursor: pointer;
}

.ganttResetBtn:hover {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--line-strong);
}

.ganttLegend {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: var(--t-0);
  color: var(--ink-soft);
}

.ganttLegendItem {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ganttSwatch {
  width: 10px;
  height: 8px;
  border-radius: 2px;
  display: inline-block;
}

.swatchAdmit {
  background: var(--accent);
}

.swatchTransit {
  background: var(--svc-north);
}

.swatchLeave {
  background: var(--gilt-soft);
  background-image: repeating-linear-gradient(45deg, transparent, transparent 2px, rgba(0, 0, 0, 0.15) 2px, rgba(0, 0, 0, 0.15) 4px);
  border: 1px dashed #d4a34b;
}

.swatchDisch {
  background: var(--good);
}

.swatchPred {
  background: var(--warn-soft);
  border: 1px solid var(--warn);
}

.swatchDelay {
  background: var(--danger);
}

/* Split Area */
.diagSplit {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem);
  align-items: stretch;
  position: relative;
}

.diagSplit.enlarged {
  grid-template-columns: 1fr;
}

.diagMain {
  display: flex;
  flex-direction: column;
  min-width: 0;
  position: relative;
}

.diagWrap {
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  background: var(--surface);
  position: relative;
  scrollbar-gutter: stable;
}

.diagWrap:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Gantt Table */
.ganttGridTable {
  width: 100%;
  min-width: 760px;
  display: flex;
  flex-direction: column;
  position: relative;
  user-select: none;
}

.ganttHeaderRow {
  display: flex;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  position: sticky;
  top: 0;
  z-index: 10;
}

.ganttColWard {
  width: 175px;
  min-width: 175px;
  padding: 7px 12px;
  font-family: var(--mono);
  font-size: var(--t-0);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 600;
  border-right: 1px solid var(--line);
  background: var(--surface-2);
  display: flex;
  align-items: center;
}

.ganttColTicks {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
}

.ganttTick {
  padding: 7px 4px;
  text-align: center;
  font-family: var(--mono);
  font-size: var(--t-0);
  color: var(--ink-soft);
  border-right: 1px solid var(--line);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ganttTick.nowTick {
  font-weight: 700;
  color: var(--accent-ink);
  background: var(--accent-soft);
}

/* Scrubber Cursor */
.ganttCursor {
  position: absolute;
  top: 28px;
  bottom: 0;
  width: 2px;
  background: var(--accent);
  z-index: 20;
  pointer-events: none;
  box-shadow: 0 0 6px rgba(47, 76, 102, 0.4);
  transition: left 0.08s ease-out;
}

.ganttCursorPin {
  position: absolute;
  top: -24px;
  left: -28px;
  background: var(--accent);
  color: var(--on-accent);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--r1);
  white-space: nowrap;
}

.ganttCursorPin::after {
  content: "";
  position: absolute;
  bottom: -3px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 3px 3px 0;
  border-style: solid;
  border-color: var(--accent) transparent transparent;
}

/* Lane Row */
.ganttLaneRow {
  display: flex;
  border-bottom: 1px solid var(--line);
  height: 34px;
  min-height: 34px;
  align-items: center;
  transition: background 0.1s ease;
}

.ganttLaneRow:hover {
  background: var(--surface-2);
}

.ganttLaneLabel {
  width: 175px;
  min-width: 175px;
  height: 100%;
  padding: 0 12px;
  border-right: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-size: var(--t-1);
  font-weight: 600;
  background: var(--surface);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ganttSvcTag {
  font-family: var(--mono);
  font-size: 9.5px;
  padding: 1px 4px;
  border-radius: var(--r1);
  background: var(--sunk);
  border: 1px solid var(--line);
  color: var(--muted);
  font-weight: 600;
  flex-shrink: 0;
}

.ganttLaneTrack {
  flex: 1;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  position: relative;
}

.ganttLaneCol {
  border-right: 1px solid var(--line-strong);
  opacity: 0.25;
  height: 100%;
}

.ganttLaneCol:nth-child(even) {
  background: rgba(125, 140, 160, 0.03);
}

/* Event Bar */
.ganttBarItem {
  position: absolute;
  top: 6px;
  height: 20px;
  min-width: 52px;
  border-radius: var(--r1);
  font-size: 10.5px;
  font-family: var(--mono);
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 0 5px;
  gap: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  z-index: 5;
  border: 1px solid transparent;
}

.ganttBarItem:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.22);
  z-index: 15;
}

.ganttBarItem:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 1px;
  z-index: 25;
}

/* High Contrast Event Bar Swatches */
.barAdmit {
  background: var(--accent);
  color: #08131a;
  border-color: rgba(255, 255, 255, 0.2);
}

.barTransit {
  background: var(--svc-north);
  color: #120d1e;
  border-color: rgba(255, 255, 255, 0.25);
}

.barLeave {
  background: var(--gilt-soft);
  background-image: repeating-linear-gradient(45deg, transparent, transparent 4px, rgba(255, 216, 133, 0.08) 4px, rgba(255, 216, 133, 0.08) 8px);
  color: #ffd885;
  border: 1px dashed #d4a34b;
}

.barDisch {
  background: var(--good);
  color: #0b1510;
  border-color: rgba(255, 255, 255, 0.2);
}

.barPred {
  background: var(--warn-soft);
  border: 1px solid var(--warn);
  color: #fedb88;
}

.barDelay {
  background: var(--danger);
  color: #1a0805;
  border-color: rgba(255, 255, 255, 0.2);
}

.activeSelect {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
  z-index: 18;
}

/* Diagram Footer */
.diagFoot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-top: 1px solid var(--line);
  background: var(--surface-2);
  font-size: var(--t-0);
  color: var(--muted);
  flex-wrap: wrap;
}

.diagScope {
  font-family: var(--mono);
  font-weight: 500;
}

.schematic {
  font-style: italic;
}

/* Tooltip */
.tooltip {
  position: absolute;
  z-index: 50;
  pointer-events: none;
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--r2);
  padding: 8px 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
  font-size: var(--t-0);
  line-height: 1.4;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 280px;
}

.tooltipTitle {
  font-weight: 700;
  color: var(--ink);
  font-family: var(--mono);
}

.tooltipDetails {
  color: var(--muted);
  font-size: 11px;
}

/* Side Corridor Rail */
.corridorRail {
  min-width: 0;
  border-left: 1px solid var(--line);
  background: var(--surface);
}

.corridorRailHeader {
  display: grid;
  gap: 0.6rem;
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid var(--line);
}

.corridorRailHeader h3 {
  margin: 0;
  color: var(--accent-ink);
  font-family: var(--display);
  font-size: var(--t-3);
  font-weight: 600;
}

.corridorTabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem;
}

.corridorTabs button {
  display: flex;
  min-height: 2.25rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  padding: 0.4rem 0.55rem;
  border: 1px solid var(--line);
  border-radius: var(--r1);
  color: var(--muted);
  background: var(--surface);
  font: inherit;
  font-size: var(--t-0);
  cursor: pointer;
  transition: all 0.12s ease;
}

.corridorTabs button:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.corridorTabs button[aria-pressed="true"] {
  border-color: var(--accent);
  color: var(--accent-ink);
  background: var(--accent-soft);
  font-weight: 600;
}

.corridorTabs span {
  font-family: var(--mono);
  font-weight: 700;
}

.corridorRanks {
  max-height: 27rem;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  list-style: none;
}

.corridorRanks li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.75rem;
  padding: 0.65rem 0.875rem;
  border-bottom: 1px solid var(--line);
}

.corridorRanks li:hover {
  background: var(--surface-2);
}

.corridorRanks li > span {
  display: grid;
  gap: 0.2rem;
  font-size: var(--t-1);
}

.corridorRanks li > span small {
  color: var(--muted);
  font-size: var(--t-0);
}

.corridorRanks li > strong {
  align-self: center;
  font-family: var(--mono);
  font-size: var(--t-1);
}

.railEmpty {
  padding: 1.25rem 0.875rem;
  margin: 0;
  color: var(--muted);
  font-size: var(--t-0);
}

