}

const TYPE_STYLE_MAP: Record<ClinicalEventType, string> = {
  admit: styles.barAdmit,
  transit: styles.barTransit,
  leave: styles.barLeave,
  discharge: styles.barDischarge,
  delay: styles.barDelay,
  predicted: styles.barPredicted,
};

export function HorizonGantt({
  events,
  defaultZoomHours = 48,
  onSelectEvent,
}: HorizonGanttProps) {
  const [zoomHours, setZoomHours] = useState<12 | 24 | 48>(defaultZoomHours);
  const [scrubHours, setScrubHours] = useState<number>(0);
  const [selectedEvent, setSelectedEvent] = useState<HorizonEventItem | null>(null);

  const lastActiveTriggerRef = useRef<HTMLElement | null>(null);
  const drawerRef = useRef<HTMLDivElement>(null);

  // Group events by discrete ward lanes
  const laneGroups = useMemo(() => {
    return groupEventsByLane(events, "wardName");
  }, [events]);

  const laneNames = useMemo(() => Object.keys(laneGroups), [laneGroups]);

  // Handle Event Click & Focus Transition
  const handleEventClick = useCallback(
    (ev: HorizonEventItem, targetElement: HTMLElement) => {
      lastActiveTriggerRef.current = targetElement;
      setSelectedEvent(ev);
      onSelectEvent?.(ev);
    },
    [onSelectEvent]
  );

  // Close Detail Drawer & Restore Focus
  const handleCloseDrawer = useCallback(() => {
    setSelectedEvent(null);
    lastActiveTriggerRef.current?.focus();
  }, []);

  // Keyboard Trap & Escape Listener
  useEffect(() => {
    if (!selectedEvent) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        handleCloseDrawer();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    drawerRef.current?.querySelector<HTMLElement>('button, [tabindex="0"]')?.focus();

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [selectedEvent, handleCloseDrawer]);

  return (
    <div className={styles.horizonContainer} role="region" aria-label="Movement Horizon">
      {/* Toolbar */}
      <div className={styles.toolbar}>
        <div className={styles.toolbarTitle}>
          Movement Horizon ({events.length} movements active)
        </div>

        <div className={styles.controlsGroup}>
          {/* Zoom Buttons */}
          <div className={styles.zoomButtonGroup} role="group" aria-label="Timeline zoom range">
            {([12, 24, 48] as const).map((h) => (
              <button
                key={h}
                type="button"
                className={`${styles.zoomBtn} ${zoomHours === h ? styles.zoomBtnActive : ""}`}
                onClick={() => setZoomHours(h)}
                aria-pressed={zoomHours === h}
              >
                {h}h
              </button>
            ))}
          </div>

          {/* Time Scrubber */}
          <div className={styles.scrubberWrapper}>
            <label htmlFor="timeline-scrubber">Time Scrub:</label>
            <input
              id="timeline-scrubber"
              type="range"
              className={styles.scrubberInput}
              min={0}
              max={zoomHours}
              value={scrubHours}
              onChange={(e) => setScrubHours(Number(e.target.value))}
              aria-label="Timeline time offset scrubber"
              aria-valuenow={scrubHours}
              aria-valuemin={0}
              aria-valuemax={zoomHours}
            />
            <span>T+{scrubHours}h</span>
          </div>
        </div>
      </div>

      {/* Lanes */}
      <div className={styles.laneContainer}>
        {laneNames.map((laneName) => {
          const laneEvents = laneGroups[laneName] || [];

          return (
            <div key={laneName} className={styles.laneRow}>
              <div className={styles.laneHeader} title={laneName}>
                {laneName}
              </div>

              <div className={styles.laneTrack}>
                {laneEvents.map((ev) => {
                  const layout = computeBarLayout(ev, zoomHours, scrubHours);
                  const modeClass = 
                    layout.labelMode === "id" 
                      ? styles.modeId 
                      : layout.labelMode === "compact" 
                      ? styles.modeCompact 
                      : styles.modeFull;

                  return (
                    <div
                      key={ev.id}
                      role="button"
                      tabIndex={0}
                      className={`${styles.eventBar} ${TYPE_STYLE_MAP[ev.type]} ${modeClass}`}
                      style={{
                        left: `${layout.leftPct}%`,
                        width: `${layout.widthPct}%`,
                      }}
                      onClick={(e) => handleEventClick(ev, e.currentTarget)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          handleEventClick(ev, e.currentTarget);
                        }
                      }}
                      aria-label={`${ev.patientId} ${ev.patientName} ${ev.statusLabel}`}
                    >
                      <span className={styles.eventId}>{ev.patientId}</span>
                      <span className={styles.eventStatusBadge}> · {ev.statusLabel}</span>
                      <span className={styles.eventFullTitle}> · {ev.patientName}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      {/* Detail Drawer */}
      {selectedEvent && (
        <div className={styles.drawerBackdrop} onClick={handleCloseDrawer} role="presentation">
          <div
            ref={drawerRef}
            className={styles.drawerPanel}
            role="dialog"
            aria-modal="true"
            aria-labelledby="drawer-heading"
            onClick={(e) => e.stopPropagation()}
          >
            <div className={styles.drawerHeader}>
              <h3 id="drawer-heading" className={styles.drawerTitle}>
                Movement Details
              </h3>
              <button
                type="button"
                className={styles.drawerCloseBtn}
                onClick={handleCloseDrawer}
                aria-label="Close movement details"
              >
                ✕
              </button>
            </div>

            <div className={styles.drawerBody}>
              <div style={{ marginBottom: 16 }}>
                <div style={{ fontSize: 18, fontWeight: 700 }}>{selectedEvent.patientName}</div>
                <div style={{ fontFamily: "var(--font-mono)", color: "var(--text-secondary)" }}>
                  {selectedEvent.patientId} · {selectedEvent.wardName}
                </div>
              </div>

              <div style={{ padding: 12, background: "var(--surface-sunken)", borderRadius: 6, fontSize: 13 }}>
                <div><strong>Status:</strong> {selectedEvent.statusLabel}</div>
                <div><strong>Statutory Authority:</strong> {selectedEvent.statutoryForm || "Voluntary Inpatient"}</div>
                {selectedEvent.escortRequired && (
                  <div><strong>Escort:</strong> {selectedEvent.escortRequired}</div>
                )}
                <div><strong>Planned Duration:</strong> {selectedEvent.durationHours} hours</div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { fireEvent, render, screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { HorizonGantt } from "./template-component";
import { HorizonEventItem } from "./template-derivations";

const SAMPLE_EVENTS: HorizonEventItem[] = [
  {
    id: "mov-1",
    patientId: "MRN-4012",
    patientName: "C. Higgins",
    wardId: "ward-4a",
    wardName: "FSH · Ward 4A",
    type: "admit",
    startHour: 2,
    durationHours: 14,
    statusLabel: "Admit Scheduled",
    statutoryForm: "Form 4A Transport Order",
    escortRequired: "Mental Health Transport Service",
  },
  {
    id: "mov-2",
    patientId: "MRN-8821",
    patientName: "S. Vance",
    wardId: "ward-2k",
    wardName: "RPH · Ward 2K",
    type: "leave",
    startHour: 10,
    durationHours: 6,
    statusLabel: "Leave Return",
    statutoryForm: "Form 5A Involuntary",
  },
  {
    id: "mov-3",
    patientId: "MRN-1094",
    patientName: "A. Kumar",
    wardId: "ward-w3",
    wardName: "Graylands · W3",
    type: "discharge",
    startHour: 18,
    durationHours: 2,
    statusLabel: "Discharge Ready",
  },
];

describe("HorizonGantt Component Visual & Interactive Integrity Suite", () => {
  it("renders all distinct ward lanes with their expected headers", () => {
    render(<HorizonGantt events={SAMPLE_EVENTS} />);

    const region = screen.getByRole("region", { name: "Movement Horizon" });
    expect(region).toBeInTheDocument();

    expect(within(region).getByTitle("FSH · Ward 4A")).toBeInTheDocument();
    expect(within(region).getByTitle("RPH · Ward 2K")).toBeInTheDocument();
    expect(within(region).getByTitle("Graylands · W3")).toBeInTheDocument();
  });

  it("renders zoom controls with 48h active and allows switching to 12h and 24h", () => {
    render(<HorizonGantt events={SAMPLE_EVENTS} defaultZoomHours={48} />);

    const btn48 = screen.getByRole("button", { name: "48h" });
    const btn24 = screen.getByRole("button", { name: "24h" });
    const btn12 = screen.getByRole("button", { name: "12h" });

    expect(btn48).toHaveAttribute("aria-pressed", "true");
    expect(btn24).toHaveAttribute("aria-pressed", "false");

    fireEvent.click(btn24);
    expect(btn24).toHaveAttribute("aria-pressed", "true");
    expect(btn48).toHaveAttribute("aria-pressed", "false");

    fireEvent.click(btn12);
    expect(btn12).toHaveAttribute("aria-pressed", "true");
  });

  it("renders the time scrubber with accessible slider attributes and updates on input", () => {
    render(<HorizonGantt events={SAMPLE_EVENTS} defaultZoomHours={24} />);

    const scrubber = screen.getByLabelText("Timeline scrubber") as HTMLInputElement;
    expect(scrubber).toBeInTheDocument();
    expect(scrubber.min).toBe("0");
    expect(scrubber.max).toBe("24");

    fireEvent.change(scrubber, { target: { value: "6" } });
    expect(scrubber.value).toBe("6");
    expect(screen.getByText("T+6h")).toBeInTheDocument();
  });

  it("opens the detail drawer when an event bar is clicked and traps focus", () => {
    render(<HorizonGantt events={SAMPLE_EVENTS} />);

    const eventBar = screen.getByRole("button", { name: /MRN-4012/i });
    fireEvent.click(eventBar);

    const drawer = screen.getByRole("dialog", { name: "Movement Details" });
    expect(drawer).toBeInTheDocument();

    expect(within(drawer).getByText("C. Higgins")).toBeInTheDocument();
    expect(within(drawer).getByText(/Form 4A Transport Order/i)).toBeInTheDocument();
    expect(within(drawer).getByText(/Mental Health Transport Service/i)).toBeInTheDocument();
  });

  it("closes the detail drawer when pressing the Escape key", () => {
    render(<HorizonGantt events={SAMPLE_EVENTS} />);

    const eventBar = screen.getByRole("button", { name: /MRN-4012/i });
    fireEvent.click(eventBar);

    expect(screen.getByRole("dialog", { name: "Movement Details" })).toBeInTheDocument();

    fireEvent.keyDown(window, { key: "Escape" });
    expect(screen.queryByRole("dialog", { name: "Movement Details" })).not.toBeInTheDocument();
  });
});

